pm.test("GET usuario inexistente devuelve 404", function () {
    pm.response.to.have.status(404);
});

pm.test("La respuesta de error no contiene un usuario válido", function () {
    const data = pm.response.json();
    pm.expect(data).to.be.an("object");
    pm.expect(data).to.not.have.property("id");
});

pm.test("Successful POST request", function () {
    pm.expect(pm.response.code).to.be.oneOf([200, 201]);
});

const data = pm.response.json();
pm.environment.set("newUserId", data.id);

pm.test("El usuario fue creado correctamente", function () {
    pm.expect(data.name).to.eql("Ailyn");
});

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Hay 10 usuarios", function () {
    const data = pm.response.json();
    pm.expect(data).to.have.length(10);
});

pm.test("Todos los usuarios tienen nombre", function () {
    const data = pm.response.json();

    data.forEach(function(usuario) {
        pm.expect(usuario).to.have.property("name");
    });
});

pm.test("Todos los usuarios tienen email", function () {
    const data = pm.response.json();

    data.forEach(function(usuario) {
        pm.expect(usuario.email).to.be.a("string");
        pm.expect(usuario.email).to.include("@");
    });
});

pm.test("El filtro devuelve el usuario con id 3", function () {
    const data = pm.response.json();
    pm.expect(data[0].id).to.eql(3);
});

pm.test("La autenticación fue correcta", function () {
    pm.response.to.have.status(200);
});

pm.test("El usuario está autenticado", function () {
    const data = pm.response.json();
    pm.expect(data.authenticated).to.eql(true);
});

pm.test("El ID del usuario es correcto", function () {
    const data = pm.response.json();
    pm.expect(data.id).to.eql(1);
});

const data = pm.response.json();
pm.environment.set("userId", data.id);

pm.test("El usuario solicitado coincide con el ID", function () {
    const data = pm.response.json();
    pm.expect(data.id).to.eql(Number(pm.environment.get("userId")));
});

pm.test("El usuario tiene los campos obligatorios", function () {
    const data = pm.response.json();

    pm.expect(data).to.have.property("id");
    pm.expect(data).to.have.property("name");
    pm.expect(data).to.have.property("email");
});

pm.test("Los tipos de datos son correctos", function () {
    const data = pm.response.json();

    pm.expect(data.id).to.be.a("number");
    pm.expect(data.name).to.be.a("string");
    pm.expect(data.email).to.be.a("string");
});

pm.test("El email tiene un formato básico válido", function () {
    const data = pm.response.json();

    pm.expect(data.email).to.match(/^[^\s@]+@[^\s@]+\.[^\s@]+$/);
});


pm.test("La validación rechaza un email inválido", function () {
    const email = "ailyn-sin-arroba.com";
    const formatoValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    pm.expect(formatoValido.test(email)).to.eql(false);
});
